"""Immutable puzzle objects. No web dependencies and no solving algorithm."""

from __future__ import annotations

import calendar
import json
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from datetime import date
from functools import cached_property
from importlib.resources import files
from types import MappingProxyType

PUZZLE_VERSION = "honeycomb-1"
SCHEMA_VERSION = 1


@dataclass(frozen=True, slots=True, order=True)
class HexCoordinate:
    q: int
    r: int

    def __post_init__(self) -> None:
        if type(self.q) is not int or type(self.r) is not int:
            raise ValueError("Hex coordinates must be integers, not booleans or decimals")

    def __add__(self, other: HexCoordinate) -> HexCoordinate:
        return HexCoordinate(self.q + other.q, self.r + other.r)

    def __sub__(self, other: HexCoordinate) -> HexCoordinate:
        return HexCoordinate(self.q - other.q, self.r - other.r)

    def rotate(self, steps: int = 1) -> HexCoordinate:
        q, r = self.q, self.r
        for _ in range(steps % 6):
            q, r = -r, q + r
        return HexCoordinate(q, r)

    def reflect(self) -> HexCoordinate:
        return HexCoordinate(self.r, self.q)

    def neighbors(self) -> tuple[HexCoordinate, ...]:
        return tuple(
            self + HexCoordinate(q, r)
            for q, r in ((1, 0), (1, -1), (0, -1), (-1, 0), (-1, 1), (0, 1))
        )

    def to_dict(self) -> dict:
        return {"q": self.q, "r": self.r}


def normalize(cells: Iterable[HexCoordinate]) -> frozenset[HexCoordinate]:
    cells = frozenset(cells)
    if not cells:
        raise ValueError("A piece must contain cells")
    anchor = min(cells)
    return frozenset(c - anchor for c in cells)


@dataclass(frozen=True, slots=True)
class Orientation:
    rotation: int
    flipped: bool
    cells: frozenset[HexCoordinate]


@dataclass(frozen=True, slots=True)
class Piece:
    id: str
    color_key: str
    cells: frozenset[HexCoordinate]

    def transformed(self, rotation: int = 0, flipped: bool = False) -> frozenset[HexCoordinate]:
        if type(rotation) is not int or not 0 <= rotation <= 5 or type(flipped) is not bool:
            raise ValueError("Rotation must be an integer 0–5; flipped must be boolean")
        return normalize((c.reflect() if flipped else c).rotate(rotation) for c in self.cells)

    def orientations(self) -> tuple[Orientation, ...]:
        seen = set()
        result = []
        for flipped in (False, True):
            for rotation in range(6):
                cells = self.transformed(rotation, flipped)
                if cells not in seen:
                    seen.add(cells)
                    result.append(Orientation(rotation, flipped, cells))
        return tuple(result)


@dataclass(frozen=True, slots=True)
class BoardCell:
    coordinate: HexCoordinate
    value: str
    type: str


@dataclass(frozen=True)
class Board:
    cells: tuple[BoardCell, ...]

    @cached_property
    def coordinates(self) -> frozenset[HexCoordinate]:
        return frozenset(c.coordinate for c in self.cells)

    @cached_property
    def by_value(self) -> Mapping[str, BoardCell]:
        return MappingProxyType({c.value: c for c in self.cells})

    def exposed(self, value: date) -> frozenset[HexCoordinate]:
        return frozenset(
            self.by_value[v].coordinate
            for v in (
                calendar.month_abbr[value.month],
                str(value.day),
                calendar.day_abbr[value.weekday()],
            )
        )


def iso_date(value: object) -> date:
    if not isinstance(value, str) or len(value) != 10:
        raise ValueError("Date must be YYYY-MM-DD")
    return date.fromisoformat(value)


@dataclass(frozen=True, slots=True)
class Challenge:
    id: str
    date: date
    title: str = "Honeycomb challenge"
    puzzle_version: str = PUZZLE_VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.id, str) or not self.id.strip():
            raise ValueError("Challenge ID must be nonempty")
        if type(self.date) is not date or self.puzzle_version != PUZZLE_VERSION:
            raise ValueError("Invalid challenge date or unsupported puzzle version")

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "date": self.date.isoformat(),
            "title": self.title,
            "puzzle_version": self.puzzle_version,
        }

    @classmethod
    def from_dict(cls, data: dict) -> Challenge:
        if not isinstance(data, dict) or set(data) != {"id", "date", "title", "puzzle_version"}:
            raise ValueError("Challenge must have id, date, title and puzzle_version")
        if not all(isinstance(data[k], str) for k in data):
            raise ValueError("Challenge fields must be strings")
        return cls(data["id"], iso_date(data["date"]), data["title"], data["puzzle_version"])


@dataclass(frozen=True, slots=True)
class Placement:
    piece_id: str
    origin: HexCoordinate
    rotation: int
    flipped: bool
    cells: frozenset[HexCoordinate]

    def to_dict(self) -> dict:
        return {
            "piece_id": self.piece_id,
            "origin": self.origin.to_dict(),
            "rotation": self.rotation,
            "flipped": self.flipped,
            "cells": [c.to_dict() for c in sorted(self.cells)],
        }


_definition = json.loads(files("daydokuthon").joinpath("data/honeycomb-1.json").read_text())
BOARD = Board(
    tuple(
        BoardCell(HexCoordinate(c["q"], c["r"]), c["value"], c["type"])
        for c in _definition["cells"]
    )
)
PIECES = tuple(
    Piece(p["id"], p["color_key"], frozenset(HexCoordinate(**c) for c in p["cells"]))
    for p in _definition["pieces"]
)
PIECES_BY_ID = MappingProxyType({p.id: p for p in PIECES})
if len(BOARD.coordinates) != 50 or len(PIECES) != 12 or sum(len(p.cells) for p in PIECES) != 47:
    raise RuntimeError("Invalid bundled puzzle definition")


def puzzle_metadata(challenge: Challenge) -> dict:
    return {
        "puzzle_version": PUZZLE_VERSION,
        "cells": [
            {**c.coordinate.to_dict(), "value": c.value, "type": c.type} for c in BOARD.cells
        ],
        "pieces": [
            {"id": p.id, "color_key": p.color_key, "cells": [c.to_dict() for c in sorted(p.cells)]}
            for p in PIECES
        ],
        "exposed": [c.to_dict() for c in sorted(BOARD.exposed(challenge.date))],
    }
